def _warn_if_value_exceeds_max_size(key: str, value: JsonValue) -> None:
    """
    Log a warning when the serialized ``value`` exceeds the configured size limit.

    The limit is ``[state_store] max_value_storage_bytes``; ``0`` disables the check.
    The write is not blocked here — the public API enforces the limit and rejects
    oversized values — but the warning gives task authors early feedback.
    """
    max_bytes = conf.getint("state_store", "max_value_storage_bytes", fallback=0)
    if max_bytes <= 0:
        return
    try:
        size = len(json.dumps(value).encode("utf-8"))
    except (TypeError, ValueError):
        return
    if size > max_bytes:
        log.warning(
            "State store value for key %r is %d bytes, which exceeds the configured "
            "[state_store] max_value_storage_bytes limit of %d bytes; the API may reject this write",
            key,
            size,
            max_bytes,
        )


